#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=7

banner "Q3A OSP server setup"

# ── Container engine ──────────────────────────────────────────────────────
stage "Container engine"
ENGINE=""
if command -v docker >/dev/null 2>&1; then ENGINE=docker
elif command -v podman >/dev/null 2>&1; then ENGINE=podman
fi
if [[ -z "$ENGINE" ]]; then
  warn "no docker or podman found on this machine"
  open_url "https://docs.docker.com/get-docker/"
  say "Install one (Docker Desktop on Windows/macOS), then re-run this wizard."
  exit 1
fi
say "Using $ENGINE ($("$ENGINE" --version 2>/dev/null))"
if ! "$ENGINE" info >/dev/null 2>&1; then
  warn "$ENGINE is installed but not reachable — its daemon/machine isn't running"
  step "Start it (Docker Desktop, or: podman machine start), then continue."
  pause "Press Enter when it's up"
fi

# ── Pull the image ────────────────────────────────────────────────────────
stage "Pull the image"
IMAGE="git.michalkozak.cz/wokoman/quake3-osp-server"
say "Canonical image: $IMAGE"
if ! "$ENGINE" pull "$IMAGE"; then
  note "Falling back to the public Docker Hub mirror..."
  IMAGE="wokoman/quake3-osp-server"
  if ! "$ENGINE" pull "$IMAGE"; then
    warn "couldn't pull from either registry"
    open_url "https://git.michalkozak.cz/wokoman/docker-quake3-osp-server"
    step "See the README's maintainer notes on build & release (Forgejo pulls may need a login), then re-run."
    exit 1
  fi
fi
say "Pulled: $IMAGE"

# ── Find pak0.pk3 ─────────────────────────────────────────────────────────
stage "Find pak0.pk3"
PAK0=""
for candidate in \
  "$HOME/.local/share/Steam/steamapps/common/Quake 3 Arena/baseq3/pak0.pk3" \
  "$HOME/Library/Application Support/Steam/steamapps/common/Quake 3 Arena/baseq3/pak0.pk3" \
  "/c/Program Files (x86)/Steam/steamapps/common/Quake 3 Arena/baseq3/pak0.pk3" \
  "/mnt/c/Program Files (x86)/Steam/steamapps/common/Quake 3 Arena/baseq3/pak0.pk3" \
  "$HOME/quake3/baseq3/pak0.pk3"; do
  if [[ -f "$candidate" ]]; then PAK0="$candidate"; break; fi
done
if [[ -n "$PAK0" ]]; then
  say "Found: $PAK0"
  if ! confirm "Use this pak0.pk3?"; then PAK0=""; fi
fi
while [[ -z "$PAK0" ]]; do
  ask PAK0 "Full path to your pak0.pk3:"
  if [[ ! -f "$PAK0" ]]; then warn "no file at that path"; PAK0=""; fi
done

# ── Start the server ──────────────────────────────────────────────────────
stage "Start the server"
MOUNT_OPTS="ro"
if [[ -d /sys/fs/selinux ]] || command -v getenforce >/dev/null 2>&1; then
  MOUNT_OPTS="ro,Z"
  note "SELinux detected — mount options: :$MOUNT_OPTS"
fi
CREATE=1
if "$ENGINE" container inspect q3aospserver >/dev/null 2>&1; then
  warn "a container named q3aospserver already exists"
  if confirm "Remove it and create a fresh one?"; then
    "$ENGINE" rm -f q3aospserver >/dev/null
  else
    CREATE=0
    say "Keeping the existing container."
  fi
fi
if (( CREATE )); then
  note "$ENGINE run --name q3aospserver -d --restart=always -p 27960:27960/udp \\\n  -v \"$PAK0:/usr/share/games/quake3/baseq3/pak0.pk3:$MOUNT_OPTS\" $IMAGE"
  if confirm "Start the server?"; then
    if "$ENGINE" run --name q3aospserver -d --restart=always -p 27960:27960/udp \
        -v "$PAK0:/usr/share/games/quake3/baseq3/pak0.pk3:$MOUNT_OPTS" "$IMAGE"; then
      say "Server starting (container q3aospserver)."
    else
      SKIPPED+=("start the server container")
    fi
  else
    SKIPPED+=("start the server container")
  fi
fi

# ── Start at boot ─────────────────────────────────────────────────────────
stage "Start at boot"
if [[ "$ENGINE" == podman ]] && command -v systemctl >/dev/null 2>&1; then
  say "Rootless podman needs one helper enabled for restart-on-boot:"
  note "systemctl --user enable --now podman-restart.service"
  if confirm "Run it now?"; then
    if systemctl --user enable --now podman-restart.service; then
      say "Enabled."
    else
      SKIPPED+=("enable podman-restart.service")
    fi
  else
    SKIPPED+=("enable podman-restart.service")
  fi
  say "That covers login. For boot-before-login, linger is needed:"
  note "loginctl enable-linger   (may ask for your password)"
  if confirm "Run it now?"; then
    if loginctl enable-linger; then say "Linger enabled."; else SKIPPED+=("loginctl enable-linger"); fi
  fi
elif [[ "$ENGINE" == docker ]] && [[ "$(uname -s)" == Linux ]]; then
  say "System docker starts at boot — the --restart=always policy covers it."
else
  step "Docker Desktop: Settings → General → enable 'Start Docker Desktop when you sign in'."
  open_url "https://docs.docker.com/desktop/settings-and-maintenance/settings/"
  pause "Press Enter when done"
fi

# ── Firewall ──────────────────────────────────────────────────────────────
stage "Firewall"
OPENED=0
if command -v firewall-cmd >/dev/null 2>&1 && firewall-cmd --state >/dev/null 2>&1; then
  if firewall-cmd --query-port=27960/udp >/dev/null 2>&1; then
    say "UDP 27960 already allowed (firewalld)."
    OPENED=1
  else
    warn "firewalld is active and UDP 27960 is not allowed yet"
    note "sudo firewall-cmd --permanent --add-port=27960/udp && sudo firewall-cmd --reload"
    if confirm "Run it now?"; then
      if sudo firewall-cmd --permanent --add-port=27960/udp && sudo firewall-cmd --reload; then
        say "Opened."
        OPENED=1
      fi
    fi
  fi
elif command -v ufw >/dev/null 2>&1 && ufw status 2>/dev/null | grep -q "Status: active"; then
  note "sudo ufw allow 27960/udp"
  if confirm "ufw is active — run it now?"; then
    if sudo ufw allow 27960/udp; then say "Opened."; OPENED=1; fi
  fi
else
  say "No active firewall detected on this machine."
  OPENED=1
fi
if (( OPENED == 0 )); then
  SKIPPED+=("allow inbound UDP 27960 in your firewall")
fi

# ── Verify & play ─────────────────────────────────────────────────────────
stage "Verify & play"
say "Giving the server a few seconds to load the map..."
sleep 5
STATUS=0
if command -v python3 >/dev/null 2>&1; then
  if python3 -c 'import socket
s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
s.settimeout(3)
s.sendto(b"\xff\xff\xff\xffgetstatus", ("127.0.0.1", 27960))
reply = s.recvfrom(65536)[0].decode("latin-1")
assert "statusResponse" in reply, reply[:80]
print("  server answered getstatus")'; then
    STATUS=1
  fi
fi
if (( STATUS == 0 )); then
  warn "no automatic answer from the server yet"
  step "Check the logs: $ENGINE logs q3aospserver (first boot can take a moment)"
  SKIPPED+=("server did not answer getstatus yet")
else
  say "Server is answering on UDP 27960."
fi
LAN_IP=$(hostname -I 2>/dev/null | awk '{print $1}')
if [[ -z "$LAN_IP" ]] && command -v ipconfig >/dev/null 2>&1; then
  LAN_IP=$(ipconfig getifaddr en0 2>/dev/null || true)
fi
say "Players join from the Q3 console with: connect ${LAN_IP:-<your LAN IP>}"
note "Logs: $ENGINE logs q3aospserver — rcon password is kolikchcesparku (see the README warning)"

finish
}

run_wizard "$@"; exit
